pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash, uint256 payment) public {
        // 1. Restrict to admissible domain: payment allowed in the buggy version (0 ether) but invalid in original (0 ether fails).
        //    The fuzzer must explore both 0 and 1 ether for the invariant to flag the bug without hardcoding.
        //    Bound payment to [0, 1 ether] to keep search manageable.
        vm.assume(payment <= 1 ether);

        // 2. Set up the caller with sufficient Ether.
        address actor = makeAddr("actor");
        vm.deal(actor, payment + 1 ether); // extra 1 ether for any later settle refund to avoid test revert on refund
        uint256 balanceBefore = address(c).balance;

        // 3. Drive the lockInGuess function under test.
        vm.prank(actor);
        try c.lockInGuess{value: payment}(hash) {
            // The invariant: if the call succeeds, the contract balance MUST have increased by exactly 1 ether.
            // The original requires(msg.value == 1 ether) guarantees this; the buggy version succeeds with 0 ether,
            // increasing the balance by 0 ether, thus violating assertTrue(increase == 1 ether).
            uint256 balanceAfter = address(c).balance;
            uint256 balanceIncrease = balanceAfter - balanceBefore;
            assertTrue(balanceIncrease == 1 ether);
        } catch {
            // If the call reverts, the original only reverts when payment != 1 ether; the buggy version only reverts when
            // guesses[actor].block != 0 (already locked) or payment != 0. We make no assertion on reverts.
        }
    }
}

