pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash1, bytes32 hash2, uint256 actorSeed) public {
        // Use multiple actors to avoid address collisions
        address user = address(uint160(uint256(keccak256(abi.encodePacked(actorSeed, "user")))));
        // Ensure we can send enough ether
        vm.deal(user, 10 ether);

        // First lockInGuess
        vm.prank(user);
        c.lockInGuess{value: 1 ether}(hash1);

        // Settle the first guess
        vm.roll(block.number + 2);
        vm.prank(user);
        c.settle();

        // Now attempt a second lockInGuess
        vm.prank(user);
        c.lockInGuess{value: 1 ether}(hash2);

        // After the second lockInGuess, the block must NOT be zero because the reference enforces block == 0 initially.
        // In reference, the second lockInGuess would revert (block is already zero after settle) so we catch revert.
        // In the bug, it succeeds and block becomes non-zero. We assert that the contract reaches a state where any
        // call to lockInGuess that doesn't revert must set block to non-zero. Concretely, we check that if the second
        // call didn't revert, the guess block is non-zero.
        (bool success, ) = address(c).call(abi.encodeWithSignature("guesses(address)", user));
        if (success) {
            (uint blockNum, ) = abi.decode(vm.getReturnData(), (uint256, bytes32));
            // Reference: second lockInGuess always reverts (block == 0), so success is false and we never reach here.
            // Bug: it succeeds, so we assert blockNum != 0, which holds for the bug but the reference never violates because it reverts.
            assertTrue(blockNum != 0);
        }
        // Note: the reference always reverts on the second call, so success is false and the assert is skipped.
        // For the bug, success is true and the assert checks the non-zero block.
        // This captures the behavioral difference: the reference never allows the second lockInGuess; the bug does and leaves a non-zero block.
    }
}

