pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C{value: 1 ether}();
    }
    function testFuzz_property(bytes32 hash1, bytes32 hash2, uint256 warpBlocks) public {
        vm.assume(warpBlocks >= 1 && warpBlocks <= 256);
        address actor = address(0x1234);
        vm.deal(actor, 2 ether);

        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash1);

        uint256 blockNum = block.number + warpBlocks;
        vm.roll(blockNum);

        vm.prank(actor);
        c.settle();

        (bool successBefore,) = address(actor).call{value: 0}("");
        require(successBefore, "actor must be callable");

        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash2);

        // After settlement + another lockInGuess, the original property: in the reference contract,
        // the second lockInGuess should revert (because block was 0, require block!=0 in mutant, but reference requires block==0).
        // We observe the guess struct via the auto-generated getter (public mapping).
        // The getter returns (uint block, bytes32 guess).
        (uint blk, bytes32 gs) = c.guesses(actor);

        // In reference: second lockInGuess succeeds (since block==0 -> block==0 passes require),
        // so block > 0 and guess == hash2.
        // In mutant: require block!=0, so after settle block=0, require fails and second lockInGuess reverts.
        // Wait, the difference statement says after lockInGuess, the state variable lockInGuess differs?
        // Actually, the state variable is guesses mapping. The difference is:
        // P allows overwriting (block==0) after settle -> succeeds, block becomes warp+1, guess hash2.
        // M requires block!=0, so after settle (block=0), lockInGuess reverts.
        // The property: after a settle that resets block to 0, a subsequent lockInGuess MUST succeed and set a new guess.
        // Reference: succeeds (since block==0). Mutant: reverts.
        // We assert that lockInGuess succeeded.
        bool lockSucceeded;
        try c.lockInGuess{value: 1 ether}(hash2) {
            lockSucceeded = true;
        } catch {
            lockSucceeded = false;
        }
        assertTrue(lockSucceeded);
    }
}

