pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 guessBlockNumber, bytes32 guessHash) public {
        // Fuzzer picks which block number the guess was locked at, keeping it admissible
        uint256 lockBlock = bound(guessBlockNumber, 1, type(uint256).max - 10);
        // Guess hash
        bytes32 hashVal = guessHash;

        // Deploy adversarial proxy that will receive the payout and forward it back to the guesser
        PayoutProxy proxy = new PayoutProxy();
        address guesser = address(proxy);

        // Fund the guesser and lock in guess
        vm.deal(guesser, 2 ether);
        vm.roll(lockBlock);
        vm.prank(guesser);
        c.lockInGuess{value: 1 ether}(hashVal);

        // Ensure the guess block number is not zero and we can settle after the guessed block
        // The guess.block is lockBlock + 1 in the contract logic, so we must be past that block
        vm.roll(lockBlock + 2);

        // Record proxy balance before settle
        uint256 proxyBalanceBefore = address(proxy).balance;

        vm.prank(guesser);
        // The settle function must be called by the guesser
        c.settle();

        // The proxy's balance after settle
        uint256 proxyBalanceAfter = address(proxy).balance;

        // General rule: if the guess was correct, the proxy (which is msg.sender) should have received 2 ether.
        // Since the proxy forwards all received ether to the original caller (itself), checking proxy balance change
        // captures whether the payout actually went to msg.sender (the guesser).
        // In the reference contract, the payout goes to msg.sender (proxy), and the proxy's balance increases by 2 ether.
        // In the mutant, payout goes to address(0), so proxy balance does NOT increase.
        // The rule: if blockhash equals guess, proxy balance must increase by 2 ether; else proxy balance must remain unchanged.
        bytes32 answer = blockhash(lockBlock + 1);
        if (answer != bytes32(0) && answer == hashVal) {
            assertTrue(proxyBalanceAfter == proxyBalanceBefore + 2 ether);
        } else {
            assertTrue(proxyBalanceAfter == proxyBalanceBefore);
        }
    }
}

// Adversarial helper: a reentrant proxy that acts as the guesser.
// It forwards all incoming ETH back to itself immediately, effectively just holding the balance.
// This is needed because fuzzed EOAs cannot execute code, but here we need to observe
// whether the payout was actually delivered to the msg.sender (the party that called settle).
// The proxy simply receives ETH and does a self-transfer to avoid reentrancy issues in settle.
contract PayoutProxy {
    receive() external payable {
        // Forward to self to ensure balance is held; the test checks balance change.
        // This is safe because C.settle() does not call back into the proxy during transfer.
        payable(address(this)).transfer(msg.value);
    }
}

