        c.settle();
        vm.prank(userB);
        c.settle();
        // invariant: contract balance >= initial (1 ether) + total ether sent in lockInGuess - 2 * number of successful guessers
        // initial = 1 ether (constructor), userA sent 1 ether, userB sent 0 ether on mutant (1 ether on reference)
        // guessers: userA (locked with 1 ether) definitely has nonzero guess; userB locked with 0 on mutant and may have a guess if the mutant store succeeded
        uint256 totalSent = 1 ether + (address(c).balance >= 1 ether ? 1 ether : 0); // we compute after calls: balance reflects actual sent
