        (uint blockA, bytes32 guessA) = c.guesses(userA);
        (uint blockB, bytes32 guessB) = c.guesses(userB);
        if (guessA != bytes32(0)) guessers++;
        if (guessB != bytes32(0)) guessers++;
        uint256 payouts = 0;
        // check if they won: a win means guess == blockhash(block) and block > lock block
        if (guessA != bytes32(0) && blockA != 0 && block.number > blockA && blockhash(blockA) == guessA) payouts += 2 ether;
        if (guessB != bytes32(0) && blockB != 0 && block.number > blockB && blockhash(blockB) == guessB) payouts += 2 ether;
        uint256 contractBalance = address(c).balance;
        // The invariant: contractBalance >= 1 ether + totalSent - payouts
        // but totalSent is not directly stored; we reconstruct from balance before payouts.
        // Simpler: the contract should never have a negative net balance after all operations.
        // The specific invariant: the sum of all locked ether minus twice the number of winning guesses must be <= contract balance.
        // Since userB sent 0 on mutant, the contract balance will be less than expected.
        uint256 lockedEther = 0;
        if (guessA != bytes32(0)) lockedEther += 1 ether;
        if (guessB != bytes32(0)) lockedEther += (address(c).balance + payouts - 1 ether - (guessA != bytes32(0) ? 1 ether : 0)); // deducing sent by userB from final balance is messy.
