contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C{value: 1 ether}();
    }

    function testFuzz_property(bytes32 guess, uint256 lockBlockNumber, uint256 settleBlockNumber) public {
        // Bound block numbers to a valid range: lockBlockNumber < settleBlockNumber, and lockBlockNumber > 0.
        vm.assume(lockBlockNumber > 0);
        vm.assume(settleBlockNumber > lockBlockNumber);
        // Bound to practical block numbers (avoid overflow, keep fuzzer efficient).
        lockBlockNumber = bound(lockBlockNumber, 1, 256);
        settleBlockNumber = bound(settleBlockNumber, lockBlockNumber + 1, 512);

        // Create a new caller address by pranking from a fresh address.
        address caller = address(uint160(uint256(keccak256(abi.encode(guess, lockBlockNumber, settleBlockNumber)))));
        vm.assume(caller != address(0));

        // Deploy a reverter helper to act as the fallback recipient when transfer fails.
        // This is an adversarial counterparty: if C tries to send ETH and it fails, the tx reverts.
        Reverter reverter = new Reverter();

        // Set up: C has 1 ETH from constructor.
        // Send 1 ETH to caller and lock in the guess at lockBlockNumber.
        vm.deal(caller, 1 ether);
        vm.roll(lockBlockNumber);
        // We need the blockhash of lockBlockNumber to equal 'guess' later.
        // The fuzzer can set guess to whatever it wants; we just need to ensure that when we call settle,
        // the blockhash(lockBlockNumber) == guess.
        // We can achieve this by patching the blockhash for lockBlockNumber to be 'guess'.
        // Since vm.mockCall is forbidden, we cannot force blockhash.
        // Instead, let the fuzzer discover a valid configuration by assuming the blockhash matches guess.
        // But we cannot call vm.expectRevert. However, we can use vm.assume to skip runs where the guess is incorrect.
        // The invariant is: IF guess == blockhash(lockBlockNumber), THEN after settle, C's balance must decrease by 2 ether.
        // So we assume the condition holds.
        vm.assume(blockhash(lockBlockNumber) == guess);

        vm.prank(caller);
        c.lockInGuess{value: 1 ether}(guess);

        // Record contract balance before settle.
        uint256 balanceBefore = address(c).balance;

        // Move to settleBlockNumber and call settle.
        vm.roll(settleBlockNumber);
        // We set the caller's code to the Reverter so that if transfer tries to send ETH, it fails.
        // That way we test the transfer path.
        // But the invariant is about balance change; if transfer reverts, the balance doesn't change either.
        // We need to ensure the transfer succeeds to observe the difference.
        // So we must NOT make it revert. We'll call settle without making the caller a contract.
        // The caller is an EOA (default). EOA transfers always succeed.
        // So we just call settle.
        vm.prank(caller);
        c.settle();

        uint256 balanceAfter = address(c).balance;

        // Assert: if the guess was correct, the balance must decrease by 2 ether.
        // Since we already assumed blockhash(lockBlockNumber) == guess, the condition is guaranteed.
        // The correct contract transfers 2 ether, so balanceAfter = balanceBefore - 2 ether.
        // The buggy contract transfers nothing, so balanceAfter = balanceBefore.
        // We assert the former.
        assertTrue(balanceAfter == balanceBefore - 2 ether);
    }
}

