pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guess, bool mismatch) public {
        // Restrict to admissible domain: guess can be anything, mismatch is a boolean
        address user = address(0x1000);
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.lockInGuess{value: 1 ether}(guess);

        // Advance to the block after the lock block
        vm.roll(block.number + 2);

        // We need to ensure that the blockhash at the locked block (block.number + 1) is either matching or not.
        // We manipulate the blockhash to control whether guess == blockhash:
        // The locked block is block.number + 1 at the time of lock.
        // We set the blockhash of that block to either guess or some other value.
        uint256 lockedBlock = block.number - 1; // after rolling, the lock block is block.number + 1 originally, now block.number - 1
        if (mismatch) {
            // Set blockhash to something different from guess
            vm.storeBlockHash(lockedBlock, bytes32(uint256(guess) ^ 0x1));
        } else {
            // Set blockhash equal to guess
            vm.storeBlockHash(lockedBlock, guess);
        }

        uint256 balBefore = address(c).balance;
        bool reverted;
        uint256 userBalBefore = user.balance;
        vm.prank(user);
        try c.settle() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 userBalAfter = user.balance;

        if (!reverted) {
            // In reference: user wins only if !mismatch (guess matched)
            // In buggy: user wins only if mismatch (guess mismatched)
            // The invariant: if mismatch, settle MUST NOT transfer 2 ether (user balance unchanged)
            // We assert that when mismatch is true, user balance does NOT increase by 2 ether.
            // This holds for reference, breaks for buggy.
            assertTrue(!mismatch || userBalAfter == userBalBefore);
        }
        // When reverted, nothing is violated.
    }
}
